// O(1) - Constante: siempre 1 operación
fun getFirst(list: List<Int>): Int = list[0]

// O(n) - Lineal: 1 pasada por cada elemento
fun findMax(list: List<Int>): Int {
    var max = list[0]
    for (item in list) {
        if (item > max) max = item
    }
    return max
}

// O(n^2) - Cuadrática: pares combinados
fun hasDuplicates(list: List<Int>): Boolean {
    for (i in list.indices) {
        for (j in i + 1 until list.size) {
            if (list[i] == list[j]) return true
        }
    }
    return false
}

// Pseudocódigo simplificado de HashMap
class SimpleHashMap<K, V>(val capacity: Int = 16) {
    private val buckets = Array<MutableList<Pair<K, V>>>(capacity) { mutableListOf() }

    fun put(key: K, value: V) {
        val index = (key.hashCode() and 0x7fffffff) % capacity
        val bucket = buckets[index]
        bucket.removeAll { it.first == key }
        bucket.add(key to value)
    }

    fun get(key: K): V? {
        val index = (key.hashCode() and 0x7fffffff) % capacity
        return buckets[index].firstOrNull { it.first == key }?.second
    }
}

fun binarySearch(sortedList: List<Int>, target: Int): Int {
    var left = 0
    var right = sortedList.size - 1

    while (left <= right) {
        val mid = left + (right - left) / 2
        when {
            sortedList[mid] == target -> return mid // ¡Encontrado!
            sortedList[mid] < target -> left = mid + 1
            else -> right = mid - 1
        }
    }
    return -1 // No encontrado
}
